package com.aditya.clashtimer.core

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.longOrNull

/**
 * Full upgrade durations from `assets/upgrade_times.json` (generated by `tools/gen_upgrade_times.cjs`
 * from the clash-of-clans-data package). `times[id][N]` = seconds to upgrade TO level N.
 * Crafted-defense modules are keyed by the module's own ID.
 */
class UpgradeTimes(private val times: Map<Int, Map<Int, Long>>) {

    val size: Int get() = times.size

    fun timeTo(dataId: Int, level: Int): Long? = times[dataId]?.get(level)

    /** Full time of [job]'s current upgrade (to `lvl + 1`), or null if the data doesn't have it. */
    fun fullTime(job: Job): Long? = timeTo(job.dataId, job.targetLevel)?.takeIf { it > 0 }

    companion object {
        val EMPTY = UpgradeTimes(emptyMap())

        fun fromJson(text: String): UpgradeTimes {
            val root = Json.parseToJsonElement(text).jsonObject
            val obj = root["times"] as? JsonObject ?: root
            return UpgradeTimes(
                obj.entries.mapNotNull { (id, levels) ->
                    val key = id.toIntOrNull() ?: return@mapNotNull null
                    val map = (levels as? JsonObject)?.entries?.mapNotNull { (lvl, secs) ->
                        val l = lvl.toIntOrNull() ?: return@mapNotNull null
                        val s = (secs as? JsonPrimitive)?.longOrNull ?: return@mapNotNull null
                        l to s
                    }?.toMap() ?: return@mapNotNull null
                    key to map
                }.toMap()
            )
        }
    }
}
